options = []

for row in value:
	lotStatus = row['lotStateName'] or ''
	if lotStatus != (row['lotStateReasonName'] or lotStatus): lotStatus = "%s (%s)"%(lotStatus, row['lotStateReasonName'])		
	options.append({'value': row['lotId'], 'label': "%s %s | %s | %s | %s %s | %s"%(row['lotId'], row['lotName'], row['itemName'], row['assetName'], row['lotEventQty'], row['itemUnitName'] or '', lotStatus)})

return options

config.script:
routeEventInfo = dict(self.view.custom.routeInfo)
userId = system.kanoa.security.getIDPUserId(self.session.props.auth.user)

if routeEventInfo['routeEventId'] is not None:
	system.perspective.sendMessage('showInfoToast', {'message': 'Updating Route Event'})	
	retVal, msg = system.kanoa.lot.updateRouteEvent(routeEventInfo, userId)
else:
	system.perspective.sendMessage('showInfoToast', {'message': 'Adding Route Event'})	
	routeEventId, msg = system.kanoa.lot.createRouteInstance(routeEventInfo['lotId'], routeEventInfo['routeId'], userId)

if msg:	system.perspective.sendMessage('showFailerToast', {'message': "Couldn't save this Route event. %s"%msg})
else: system.perspective.sendMessage('showSuccessfulToast', {'message': "Route event has been saved"})

system.perspective.sendMessage("updateRouteEvents", {})	
system.perspective.closePopup('')

return
